 void ApplyFonts(Control parent){foreach(Control child in parent.Controls){if(child!=heading)child.Font=Font;ApplyFonts(child);}}
 static Label Note(string text){var l=LabelText(text);l.ForeColor=Color.DimGray;return l;}
 void FitScreen(){var area=Screen.FromControl(this).WorkingArea;MinimumSize=new Size(Math.Min(MinimumSize.Width,area.Width-20),Math.Min(MinimumSize.Height,area.Height-20));Size=new Size(Math.Min(Width,area.Width-40),Math.Min(Height,area.Height-40));Location=new Point(area.Left+(area.Width-Width)/2,area.Top+(area.Height-Height)/2);}
 void Reflow(){if(reflow)return;reflow=true;try{float scale=previewScale??(DeviceDpi/96f);bool narrow=setup.ClientSize.Width<860*scale;int desired=narrow?1:2;if(columns.ColumnCount==desired)return;columns.SuspendLayout();columns.ColumnCount=desired;columns.ColumnStyles.Clear();for(int i=0;i<desired;i++)columns.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/desired));columns.SetCellPosition(roleBox,new TableLayoutPanelCellPosition(0,0));columns.SetCellPosition(timerBox,new TableLayoutPanelCellPosition(narrow?0:1,narrow?1:0));columns.RowCount=narrow?2:1;columns.RowStyles.Clear();for(int i=0;i<columns.RowCount;i++)columns.RowStyles.Add(new RowStyle(SizeType.AutoSize));columns.ResumeLayout(true);}finally{reflow=false;}}
 Control PathPicker(TextBox text){var panel=new TableLayoutPanel{ColumnCount=2,AutoSize=true,Dock=DockStyle.Fill,Margin=Padding.Empty};panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));panel.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));text.Dock=DockStyle.Fill;panel.Controls.Add(text,0,0);var b=ButtonText("选择");b.Margin=Padding.Empty;panel.Controls.Add(b,1,0);b.Click+=(s,e)=>{using(var dialog=new OpenFileDialog{Filter="程序 (*.exe)|*.exe",CheckFileExists=true})if(dialog.ShowDialog(this)==DialogResult.OK)text.Text=dialog.FileName;};return panel;}
 CreationConfig ReadConfig(){var c=new CreationConfig{DisplayMode=display.Text,RuleSet=rule.Text,Faction=faction.Text,Race=race.Text,Gender=gender.Text,ClassName=job.Text,FirstName=first.Text,LastName=last.Text,IntervalSeconds=(int)interval.Value,MaxAttempts=(int)rounds.Value,MaxMinutes=(int)minutes.Value,Restart=mode.SelectedIndex==0,Scheduled=scheduled.Checked,StartAt=startAt.Value,GamePath=gamePath.Text,LauncherPath=launcherPath.Text};c.Validate();return c;}
 void LoadConfig(CreationConfig c){loading=true;display.SelectedItem=c.DisplayMode;rule.SelectedItem=c.RuleSet;faction.SelectedItem=c.Faction;race.SelectedItem=c.Race;gender.SelectedItem=c.Gender;job.SelectedItem=c.ClassName;first.Text=c.FirstName;last.Text=c.LastName;interval.Value=c.IntervalSeconds;rounds.Value=c.MaxAttempts;minutes.Value=c.MaxMinutes;mode.SelectedIndex=c.Restart?0:1;scheduled.Checked=c.Scheduled;startAt.Value=c.StartAt;startAt.Enabled=c.Scheduled;gamePath.Text=c.GamePath;launcherPath.Text=c.LauncherPath;loading=false;UpdateReady();}
 void UpdateReady(){if(loading)return;try{var c=ReadConfig();bool ready=CalibrationStore.Ready(c);calibration.Text=ready?(c.Builtin?"● 已验证的默认配置，可直接开始。":"● 已校准，可开始定时运行。"):("● 这组信息尚未校准。\n请先点“预览校准”，核对角色和姓名。");calibration.ForeColor=ready?Color.FromArgb(28,119,76):Color.FromArgb(163,92,14);start.Enabled=ready&&!busy;}catch{calibration.Text="请完整填写角色配置。";calibration.ForeColor=Color.DimGray;start.Enabled=false;}}
 void Busy(bool value){busy=value;if(value){activeRunner=null;elapsed.Restart();}else elapsed.Stop();if(value)flowView.UpdateSteps(new FlowTrace().Snapshot());RefreshProgress();ShowRecord();roleBox.Enabled=!value;timerBox.Enabled=!value;paths.Enabled=!value;save.Enabled=!value;prepare.Enabled=!value;stop.Enabled=value;startAt.Enabled=scheduled.Checked&&!value;UpdateReady();}
 void Write(string text){if(IsDisposed||Disposing)return;if(InvokeRequired){try{BeginInvoke(new Action<string>(Write),text);}catch(InvalidOperationException){}return;}string line=DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")+"  "+text;log.AppendText(line+Environment.NewLine);status.Text=text;try{File.AppendAllText(AppPaths.RunLog,line+Environment.NewLine);}catch{}}
 void RefreshProgress(){var r=activeRunner;if(r!=null)flowView.UpdateSteps(r.Flow.Snapshot());string waiting="";var next=r==null?(DateTime?)null:r.NextAttemptUtc;if(busy&&next.HasValue)waiting=" · 下次开始 "+Math.Max(0,(int)Math.Ceiling((next.Value-DateTime.UtcNow).TotalSeconds))+" 秒";metrics.Text="耗时 "+elapsed.Elapsed.ToString(@"hh\:mm\:ss")+" · "+(busy?"运行中":"已停止 / 就绪")+(r==null?"":" · 第 "+r.AttemptNumber+" / "+r.AttemptLimit+" 次 · 已拦截 "+r.BlockedCount+" 次")+waiting;}
 void Warn(string text){MessageBox.Show(this,text,AppInfo.Title,MessageBoxButtons.OK,MessageBoxIcon.Information);}
 async void StartRun(){if(busy||preview)return;try{var c=ReadConfig();if(!CalibrationStore.Ready(c))throw new Exception("请先预览校准这组信息。");if(c.Scheduled&&c.StartAt<=DateTime.Now)throw new Exception("预约时间已过，请选择未来时间或取消预约。");c.Save();await ExecuteConfig(c,null);}catch(Exception ex){Warn(ex.Message);}}
 async Task ExecuteConfig(CreationConfig c,ScheduledJob job){
  Busy(true);cancel=new CancellationTokenSource();Write("v"+AppInfo.Version+" 已载入："+c.Summary);Runner runner=null;string result="已完成",message="已达到本次尝试上限；请查看结果记录。";
  try{runner=new Runner(vision,Write,cancel.Token,c);activeRunner=runner;await Task.Run(()=>runner.Run(true));runner.Flow.Finish("已完成","本次尝试结束；建号结果请核对记录。");Write("本次运行已结束。");}catch(OperationCanceledException){PauseAutomaticJobs("用户停止当前执行。");runner.Flow.Finish("已停止","用户停止或取消预约。");result="已停止";message="用户停止或取消预约。";Write(message);}catch(Exception ex){PauseAutomaticJobs(ex.Message);if(runner!=null){runner.Flow.Finish("异常",ex.Message);runner.SaveDiagnostic("调试-异常页面");}result="需检查";message=ex.Message;Write(message);}finally{cancel.Dispose();cancel=null;Busy(false);RefreshRecords();if(job!=null){job.Status=result;job.Detail=message;job.LastFinished=DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");JobStore.Save(job);activeJob=null;RefreshJobs();}}
 }
 async void Calibrate(){if(busy||preview)return;CalibrationBundle bundle=null;try{var c=ReadConfig();Busy(true);cancel=new CancellationTokenSource();var runner=new Runner(vision,Write,cancel.Token,c);activeRunner=runner;bundle=await Task.Run(()=>runner.Calibrate());runner.Flow.Finish("已完成","预览结束，未提交建号。");Native.FocusWindow(Handle);using(var review=new CalibrationReview(bundle)){if(review.ShowDialog(this)==DialogResult.OK){CalibrationStore.Save(bundle);c.Save();Write("预览已确认，配置和校准样本已保存。尚未提交建号。");}else Write("已取消校准确认，尚未提交建号。");}}catch(OperationCanceledException){PauseAutomaticJobs("用户取消预览。");if(activeRunner!=null)activeRunner.Flow.Finish("已停止","预览已取消，未提交建号。");Write("预览已取消，尚未提交建号。");}catch(Exception ex){PauseAutomaticJobs(ex.Message);if(activeRunner!=null)activeRunner.Flow.Finish("异常",ex.Message);Write("预览停止："+ex.Message);}finally{if(bundle!=null)bundle.Dispose();if(cancel!=null){cancel.Dispose();cancel=null;}Busy(false);}}
 void RefreshRecords(){var selected=Selected();grid.Rows.Clear();foreach(var r in ResultsStore.All()){int i=grid.Rows.Add(r.Time,r.Status,r.Attempt,r.Config.RuleSet+" / "+r.Config.Faction+" / "+r.Config.Race+" / "+r.Config.Gender+" / "+r.Config.ClassName,r.Config.FirstName+" · "+r.Config.LastName);grid.Rows[i].Tag=r;if(selected!=null&&r.Id==selected.Id)grid.Rows[i].Selected=true;}ShowRecord();}
 AttemptRecord Selected(){return grid.SelectedRows.Count==0?null:grid.SelectedRows[0].Tag as AttemptRecord;}
 void ShowRecord(){var r=Selected();confirm.Enabled=!busy&&r!=null&&r.Status=="待确认";detail.Text=r==null?"提交前会留档，随后更新结果。未明确判定的结果标为待确认，不会自动当成成功。":r.Config.Summary+Environment.NewLine+r.Detail+Environment.NewLine+(string.IsNullOrEmpty(r.ConfirmedAt)?"":"确认时间："+r.ConfirmedAt);}
 static void Open(string path){try{Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(ex.Message);}}
 protected override void WndProc(ref Message m){if(m.Msg==0x312){if(m.WParam.ToInt32()==8)StartRun();if(m.WParam.ToInt32()==9&&cancel!=null)cancel.Cancel();}base.WndProc(ref m);}
 public void SavePreview(string path){using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));using(var g=Graphics.FromImage(image)){foreach(var box in new[]{rule,faction,race,gender,job,mode}){if(!box.Visible)continue;if(box.SelectedIndex<0)throw new Exception("预览缺少已选配置。");var point=box.PointToScreen(Point.Empty);point.Offset(-Left+3,-Top+2);var rect=new Rectangle(point,new Size(box.Width-25,box.Height-4));var visible=rect;for(Control ancestor=box.Parent;ancestor!=null;ancestor=ancestor.Parent){var clip=ancestor.RectangleToScreen(ancestor.ClientRectangle);clip.Offset(-Left,-Top);visible=Rectangle.Intersect(visible,clip);}if(visible.IsEmpty)continue;var state=g.Save();g.SetClip(visible);g.FillRectangle(Brushes.White,rect);using(var previewFont=new Font(Font.FontFamily,11f*(previewScale??(DeviceDpi/96f))/(DeviceDpi/96f)))TextRenderer.DrawText(g,box.Text,previewFont,rect,box.ForeColor,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.PreserveGraphicsClipping);g.Restore(state);}}image.Save(path);}}
 internal void CheckLayout(){PerformLayout();Application.DoEvents();if(heading.Bounds.Bottom>subtitle.Bounds.Top)throw new Exception("标题区域重叠");foreach(var label in new[]{heading,subtitle,status}){var need=label.GetPreferredSize(new Size(label.Width,0));if(label.Height+2<need.Height)throw new Exception("文字高度不足："+label.Text);}if(start.Parent.Bottom>status.Parent.Bottom||tabs.Height<120)throw new Exception("内容或操作区高度不足");if(rule.Width<100||mode.Width<100)throw new Exception("表单输入区过窄");}
 internal void SetPreviewScale(float factor){float ratio=factor/(DeviceDpi/96f);previewScale=factor;Scale(new SizeF(ratio,ratio));SetTestFonts(this,ratio);SetNativeFonts();PerformLayout();Reflow();}
 void SetTestFonts(Control parent,float ratio){foreach(Control child in parent.Controls){child.Font=new Font(child.Font.FontFamily,(child==heading?16f:11f)*ratio,child==heading?FontStyle.Bold:FontStyle.Regular);SetTestFonts(child,ratio);}}
 internal void SelectTab(int index){tabs.SelectedIndex=index;Application.DoEvents();}
}

